 row=(l,c)=>`<tr><th scope="row">${esc(l)}</th><td>${c.t}</td><td>${c.ok}</td><td>${c.pl}</td><td>${c.lt}</td><td>${c.cx}</td><td>${rate(c)}</td></tr>`,
 head=f=>`<thead><tr><th>${f}</th><th>Tổng</th><th>Hoàn thành</th><th>Dự kiến</th><th>Trễ hạn</th><th>Hủy</th><th>Tỉ lệ hoàn thành</th></tr></thead>`,
