$("#dlg-form").addEventListener("click",e=>{const b=e.target.closest("button");if(!b||!S.stat||!b.id.startsWith("st-"))return;const d=new Date(S.stat);if(b.id==="st-prev")d.setMonth(d.getMonth()-1);if(b.id==="st-next")d.setMonth(d.getMonth()+1);if(b.id==="st-now"){d.setFullYear(new Date().getFullYear(),new Date().getMonth(),1)}stats(d)});
