$("#crumbs").addEventListener("click",e=>{const b=e.target.closest("[data-crumb]");if(!b)return;const t=b.dataset.crumb,r=S.edit?.region||"";if(t==="region"){go("customers");if(S.view==="customers"){$("#region-filter").value=r;cust()}}else go(t)});
function editWork(w,day){const nw=!w;
 form(nw?"Thêm công việc":"Sửa công việc",[["title","Nội dung","text","",1],["date","Ngày","date","",1],["time","Giờ","time"],["cus","Khách hàng","text","cl"],["type","Loại","sel",types],["st","Trạng thái","sel",sels],["note","Ghi chú","area"]],w||{date:day||iso(new Date()),type:types[0],st:sels[0]},async o=>{
  if(!o.title){setErr("f_title","Hãy nhập nội dung công việc.");return false}if(!o.date){setErr("f_date","Hãy chọn ngày.");return false}
  const rec={...(w||{}),...o,id:w?.id||crypto.randomUUID(),updated:Date.now()};await put("w",[rec]);await load();render();notify("Đã lưu công việc",async()=>{w?await put("w",[w]):await del("w",rec.id)})},
  `<datalist id="cl">${S.cus.map(c=>`<option value="${esc(c.name)}">`).join("")}</datalist>`,nw?null:async()=>{await del("w",w.id);await load();render();notify("Đã xóa công việc",()=>put("w",[w]))})}
