  const c={id:key(nm),name:nm,a25:num(r[1]),t26:num(r[2]),a26:num(r[5]),q:[0,1,2,3].map(k=>[num(r[8+2*k]),null]),m:Array.from({length:12},(_,k)=>[num(r[16+2*k]),num(r[17+2*k])]),region:guess(nm),updated:Date.now()};
